    if (li === 0) { qx = a; qy = b; qz = c; qw = dd; }
    else if (li === 1) { qx = dd; qy = b; qz = c; qw = a; }
    else if (li === 2) { qx = b; qy = dd; qz = c; qw = a; }
    else { qx = b; qy = c; qz = dd; qw = a; }
